(()=>{
 const q=new URLSearchParams(location.search),capture=q.get('capture')==='1';if(capture)document.body.classList.add('capture');
 MacHost.init();SteamDemo.init();let zoom='fit',selection='library';
 const pages=[['discovery','发现'],['library','游戏库'],['steam-library','Steam 游戏'],['detail','游戏详情'],['settings','常规设置'],['steam-settings','Steam 设置']];
 const details=[['overview','概览'],['achievements','成就'],['reviews','评价'],['dlc','DLC'],['mods','MOD / 工坊']];
 const scenes=[['first','首次进入 Steam'],['legacy','旧版已登录'],['ready','已登录 · 盖世游戏库'],['window','Steam · 窗口模式'],['big','Steam · 大屏模式'],['login','扫码 / 密码登录'],['accounts','账号管理'],['panel','悬浮球面板'],['panel-settings','悬浮球设置'],['metered','计费网络下载'],['component-update','旧组件待更新'],['prepare','组件准备中'],['download-error','组件下载失败'],['network-error','网络连接失败'],['sync-error','游戏列表加载失败'],['empty','空游戏库']];
 const labels=Object.fromEntries([...pages,...details,...scenes]);
 function render(){const base=MacHost.getState().baseline;document.querySelector('#demo-controls').innerHTML=`<header class="dc-brand"><span class="dc-brand-icon"><img src="${MAC_ASSETS.logo}" alt=""></span><div><strong>GameHub</strong><small>Mac · Steam 接入评审</small></div></header><div class="dc-scroll"><section class="dc-section"><span class="dc-label">方案版本</span><div class="dc-segment"><button data-dc-version="new" class="${base?'':'active'}">接入新方案</button><button data-dc-version="baseline" class="${base?'active':''}">重构原页面</button></div></section><section class="dc-section"><span class="dc-label">页面</span><div class="dc-grid">${pages.map(([v,t])=>`<button data-dc-page="${v}" class="${selection===v?'active':''}">${t}</button>`).join('')}</div></section><section class="dc-section"><span class="dc-label">游戏详情</span><div class="dc-grid">${details.map(([v,t])=>`<button data-dc-detail="${v}" class="${selection==='detail-'+v?'active':''}">${t}</button>`).join('')}</div></section><section class="dc-section"><span class="dc-label">Steam 演示</span><div class="dc-grid"><button data-dc-scene="first">首次进入</button><button data-dc-scene="window">窗口模式</button><button data-dc-scene="big">大屏模式</button></div></section><section class="dc-section"><label class="dc-label" for="dc-state">演示状态</label><select id="dc-state" class="dc-select"><option value="">选择场景</option>${scenes.map(([v,t])=>`<option value="${v}" ${selection===v?'selected':''}>${t}</option>`).join('')}</select><label class="dc-label" for="dc-network">网络场景</label><select id="dc-network" class="dc-select"><option value="unmetered" ${SteamDemo.getState().connection==='unmetered'?'selected':''}>普通 Wi-Fi / 有线</option><option value="metered" ${SteamDemo.getState().connection==='metered'?'selected':''}>按流量计费</option></select><div class="dc-tools"><button data-dc="reopen">模拟重开 App</button><button data-dc="reset">重置演示</button></div></section></div><footer class="dc-foot"><div class="dc-note"><strong>评审提示</strong><p id="dc-context">左侧为演示工具，不属于客户端。</p><p>2026.11.6修改：SDK 内页面、账号及悬浮功能为占位，以实际接入为准。</p></div></footer>`;updateContext();}
 function fit(){const board=document.querySelector('.ds-board'),frame=document.querySelector('.ds-frame'),v=document.querySelector('#demo-viewport');const scale=capture||zoom==='actual'?1:Math.min((board.clientWidth-8)/1280,(board.clientHeight-22)/835,1);v.style.setProperty('--preview-scale',Math.max(.2,scale));frame.style.width=1280*Math.max(.2,scale)+'px';frame.style.height=835*Math.max(.2,scale)+'px';document.querySelector('#ds-scale').textContent=Math.round(scale*100)+'%';document.querySelectorAll('[data-dc-zoom]').forEach(b=>b.classList.toggle('active',b.dataset.dcZoom===zoom));}
 function updateContext(){const h=MacHost.getState(),s=SteamDemo.getState();let title=labels[h.page]||'盖世游戏',note='保留重构版布局，Steam 能力按入口承接。';if(h.page==='detail'){const tab=h.detailTab||h.detailSection;title='游戏详情';note='盖世评价与 Steam 评测分开；本地 MOD 与创意工坊分开。';if(tab)title+=' · '+(labels[tab]||tab);}if(h.page==='steam-library'){title='盖世游戏库 · Steam 游戏';note='在盖世内管理和启动；原生功能按需打开 Steam 界面。';}if(s.open){if(s.screen==='mode'){title='进入 Steam';note='首次与旧登录首次勾选协议；进入后默认大屏，模式切换在悬浮球设置内。';}else if(s.screen==='prepare'){title='准备 Steam';note='2026.11.6修改：下载可关闭取消；计费网络先确认，取消后不再跳转。';}else if(s.screen==='metered'){title='下载提醒';note='2026.11.6修改：仅计费网络提示；有线或普通 Wi-Fi 不拦截。';}else if(s.screen==='login'){title='登录 Steam';note='演示扫码与密码登录，不输入真实账号。';}else{title=s.screen==='native'?'Steam 原生界面 · '+(s.displayMode==='big'?'大屏模式':'窗口模式'):'盖世游戏';note='Steam 画面和页面定位为示意，以实际接入为准。';}if(s.modal==='accounts')title='Steam 账号管理';}document.querySelector('#ds-title').textContent=title;document.querySelector('#ds-subtitle').textContent=h.baseline?'GameHub 1.0.0 · 重构版页面基线':'GameHub 1.0.0 · 窗口模式 / 大屏模式';const n=document.querySelector('#dc-context');if(n)n.textContent=note;document.querySelectorAll('[data-dc-page]').forEach(b=>b.classList.toggle('active',b.dataset.dcPage===h.page));document.querySelectorAll('[data-dc-detail]').forEach(b=>b.classList.toggle('active',h.page==='detail'&&b.dataset.dcDetail===h.detailTab));document.querySelectorAll('[data-dc-scene]').forEach(b=>b.classList.toggle('active',s.open&&(b.dataset.dcScene==='big'?s.screen==='native'&&s.displayMode==='big':b.dataset.dcScene==='window'?s.screen==='native'&&s.displayMode==='window':s.screen==='mode')));}
 function show(page){SteamDemo.close?.();selection=page;if(page==='steam-library'){MacHost.setBaseline(false);SteamDemo.scenario('ready');}else MacHost.navigate(page);render();}
 function detail(tab){SteamDemo.close?.();MacHost.setBaseline(false);selection='detail-'+tab;MacHost.showDetailTab?.(tab);render();}
 function scene(key){selection=key;MacHost.setBaseline(false);SteamDemo.scenario(key);render();}
 document.querySelector('#demo-controls').addEventListener('click',e=>{let el=e.target.closest('button');if(!el)return;if(el.dataset.dcPage)show(el.dataset.dcPage);if(el.dataset.dcDetail)detail(el.dataset.dcDetail);if(el.dataset.dcScene)scene(el.dataset.dcScene);if(el.dataset.dcVersion){SteamDemo.close?.();MacHost.setBaseline(el.dataset.dcVersion==='baseline');render();}if(el.dataset.dc==='reset'){SteamDemo.reset();MacHost.reset();selection='library';render();}if(el.dataset.dc==='reopen'){MacHost.restart();selection=MacHost.getState().landing;render();}});
 document.querySelector('#demo-controls').addEventListener('change',e=>{if(e.target.id==='dc-state'&&e.target.value)scene(e.target.value);if(e.target.id==='dc-network')SteamDemo.setConnection(e.target.value);});
 document.querySelectorAll('[data-dc-zoom]').forEach(b=>b.addEventListener('click',()=>{zoom=b.dataset.dcZoom;fit();}));
 window.MacReview={setOpen(){},show,scene,detail,baseline(v){SteamDemo.close?.();MacHost.setBaseline(v);render();},fit};
 if(q.get('baseline')==='1')MacHost.setBaseline(true);if(q.get('page'))show(q.get('page'));if(q.get('tab'))detail(q.get('tab'));if(q.get('scene'))scene(q.get('scene'));if(q.get('native')){SteamDemo.scenario('ready');MacHost.showDetailTab(q.get('native')==='workshop'?'mods':q.get('native'));SteamDemo.enter({nativePage:q.get('native'),gameId:'stardew',forceBig:true});}render();fit();
 new ResizeObserver(fit).observe(document.querySelector('.ds-board'));new MutationObserver(updateContext).observe(document.querySelector('#host-root'),{childList:true,subtree:true});new MutationObserver(updateContext).observe(document.querySelector('#steam-root'),{childList:true,subtree:true});
})();
